17	package com.google.common.cache;
18	
19	import static com.google.common.base.Preconditions.checkState;
20	
21	import com.google.caliper.BeforeExperiment;
22	import com.google.caliper.Benchmark;
23	import com.google.caliper.Param;
24	import com.google.common.cache.LocalCache.Segment;
25	import java.util.concurrent.atomic.AtomicReferenceArray;
26	import org.jspecify.annotations.NullUnmarked;
27	
28	/**
29	 * Benchmark for {@code LocalCache.Segment.expand()}.
30	 *
31	 * @author Charles Fry
32	 */
33	@NullUnmarked
34	public class SegmentBenchmark {
35	
36	  @Param({"16", "32", "64", "128", "256", "512", "1024", "2048", "4096", "8192"})
37	  int capacity;
38	
39	  private Segment<Object, Object> segment;
40	
41	  @BeforeExperiment
42	  void setUp() {
43	    LocalCache<Object, Object> cache =
44	        new LocalCache<>(
45	            CacheBuilder.newBuilder().concurrencyLevel(1).initialCapacity(capacity), null);
46	    checkState(cache.segments.length == 1);
47	    segment = cache.segments[0];
48	    checkState(segment.table.length() == capacity);
49	    for (int i = 0; i < segment.threshold; i++) {
50	      cache.put(new Object(), new Object());
51	    }
52	    checkState(segment.table.length() == capacity);
53	  }
54	
55	  @SuppressWarnings("GuardedBy")
56	  @Benchmark
57	  int time(int reps) {
58	    int dummy = 0;
59	    AtomicReferenceArray<ReferenceEntry<Object, Object>> oldTable = segment.table;
60	    for (int i = 0; i < reps; i++) {
61	      // TODO(b/145386688): This access should be guarded by 'this.segment', which is not currently
62	      // held
63	      segment.expand();
64	      segment.table = oldTable;
